'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8');

let pos = 0;
function nextInt() {
  while (pos < input.length && input.charCodeAt(pos) <= 32) pos++;
  let sign = 1;
  if (input.charCodeAt(pos) === 45) {
    sign = -1;
    pos++;
  }
  let value = 0;
  while (pos < input.length) {
    const c = input.charCodeAt(pos);
    if (c < 48 || c > 57) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value * sign;
}

const n = nextInt();
const x = new Int32Array(n);
const y = new Int32Array(n);
for (let i = 0; i < n; i++) x[i] = nextInt();
for (let i = 0; i < n; i++) y[i] = nextInt();

const u = new Int32Array(n);
const v = new Int32Array(n);
let minUAll = Infinity, maxUAll = -Infinity;
let minVAll = Infinity, maxVAll = -Infinity;

for (let i = 0; i < n; i++) {
  u[i] = x[i] + y[i];
  v[i] = x[i] - y[i];
  if (u[i] < minUAll) minUAll = u[i];
  if (u[i] > maxUAll) maxUAll = u[i];
  if (v[i] < minVAll) minVAll = v[i];
  if (v[i] > maxVAll) maxVAll = v[i];
}

const orderU = new Array(n);
const orderV = new Array(n);
for (let i = 0; i < n; i++) {
  orderU[i] = i;
  orderV[i] = i;
}
orderU.sort((a, b) => u[a] - u[b]);
orderV.sort((a, b) => v[a] - v[b]);

const state = new Uint8Array(n);
const active = new Uint8Array(n);
const queue = new Int32Array(n);

function feasible(limit) {
  state.fill(0);
  active.fill(1);

  let minU1 = Infinity, maxU1 = -Infinity;
  let minV1 = Infinity, maxV1 = -Infinity;
  let minU2 = Infinity, maxU2 = -Infinity;
  let minV2 = Infinity, maxV2 = -Infinity;

  let pMinU = 0, pMaxU = n - 1;
  let pMinV = 0, pMaxV = n - 1;

  for (let root = 0; root < n; root++) {
    if (state[root] !== 0) continue;

    state[root] = 1;
    active[root] = 0;
    minU1 = maxU1 = u[root];
    minV1 = maxV1 = v[root];

    let head = 0, tail = 0;
    queue[tail++] = root;

    while (head < tail) {
      const point = queue[head++];
      const pu = u[point];
      const pv = v[point];
      const color = state[point];

      if (color === 1) {
        if (pu < minU1 - limit || pu > maxU1 + limit ||
            pv < minV1 - limit || pv > maxV1 + limit) return false;
      } else {
        if (pu < minU2 - limit || pu > maxU2 + limit ||
            pv < minV2 - limit || pv > maxV2 + limit) return false;
      }

      while (pMinU < n && active[orderU[pMinU]] === 0) pMinU++;
      while (pMaxU >= 0 && active[orderU[pMaxU]] === 0) pMaxU--;
      while (pMinV < n && active[orderV[pMinV]] === 0) pMinV++;
      while (pMaxV >= 0 && active[orderV[pMaxV]] === 0) pMaxV--;

      while (true) {
        let next = -1;

        if (pMinU < n) {
          const i = orderU[pMinU];
          if (u[i] < pu - limit) next = i;
        }
        if (next === -1 && pMaxU >= 0) {
          const i = orderU[pMaxU];
          if (u[i] > pu + limit) next = i;
        }
        if (next === -1 && pMinV < n) {
          const i = orderV[pMinV];
          if (v[i] < pv - limit) next = i;
        }
        if (next === -1 && pMaxV >= 0) {
          const i = orderV[pMaxV];
          if (v[i] > pv + limit) next = i;
        }
        if (next === -1) break;

        active[next] = 0;
        const newColor = color === 1 ? 2 : 1;
        state[next] = newColor;

        if (newColor === 1) {
          if (u[next] < minU1) minU1 = u[next];
          if (u[next] > maxU1) maxU1 = u[next];
          if (v[next] < minV1) minV1 = v[next];
          if (v[next] > maxV1) maxV1 = v[next];
        } else {
          if (u[next] < minU2) minU2 = u[next];
          if (u[next] > maxU2) maxU2 = u[next];
          if (v[next] < minV2) minV2 = v[next];
          if (v[next] > maxV2) maxV2 = v[next];
        }

        queue[tail++] = next;

        while (pMinU < n && active[orderU[pMinU]] === 0) pMinU++;
        while (pMaxU >= 0 && active[orderU[pMaxU]] === 0) pMaxU--;
        while (pMinV < n && active[orderV[pMinV]] === 0) pMinV++;
        while (pMaxV >= 0 && active[orderV[pMaxV]] === 0) pMaxV--;
      }
    }
  }

  return true;
}

let low = 0;
let high = Math.max(maxUAll - minUAll, maxVAll - minVAll);

while (low < high) {
  const mid = Math.floor((low + high) / 2);
  if (feasible(mid)) high = mid;
  else low = mid + 1;
}

